<?php
declare(strict_types=1);
namespace App\Application\Review\Service;
use App\Application\Review\AI\NotebookAnalysisResponseValidator;use App\Domain\Review\Enum\NotebookAnalysisStatus;use App\Domain\Review\Repository\NotebookAnalysisExecutionRepositoryInterface;
final readonly class ProcessNotebookAnalysisService { public function __construct(private NotebookAnalysisExecutionRepositoryInterface $executions,private BuildNotebookPerformanceSummaryService $summary,private NotebookAnalysisResponseValidator $validator){} /** @param callable(array):array $provider @param null|callable(list<array>):void $apply */ public function execute(string $notebookId,string $userId,string $version,callable $provider,\DateTimeImmutable $now,?callable $apply=null):array{$execution=$this->executions->findByNotebookAndVersion($notebookId,$version);if($execution===null||$execution->status===NotebookAnalysisStatus::COMPLETED||$execution->retryCount>=3)return [];$execution->begin($now);$this->executions->save($execution);try{$result=$this->validator->validate($provider($this->summary->execute($userId,$notebookId)->toProviderPayload()));if($apply!==null)$apply($result);$execution->status=NotebookAnalysisStatus::COMPLETED;$execution->summary=['action_count'=>count($result)];$execution->completedAt=$now;$this->executions->save($execution);return $result;}catch(\Throwable){$execution->retryCount++;$execution->fail('ANALYSIS_PROCESSING_FAILED','Não foi possível processar a análise do caderno.',$now);$this->executions->save($execution);return [];}} }
